export function groupConsecutive(values: number[]): number[][] {
  if (values.length === 0) {
    return [];
  }

  const result: number[][] = [];
  let currentRun: number[] = [values[0]];

  for (let i = 1; i < values.length; i++) {
    const prev = values[i - 1];
    const curr = values[i];

    if (curr === prev + 1) {
      currentRun.push(curr);
    } else {
      result.push(currentRun);
      currentRun = [curr];
    }
  }

  result.push(currentRun);
  return result;
}
